abstract class NumberSource {
    abstract int nextValue();
    int plusOne() { return nextValue() + 1; }
}
class FixedValue extends NumberSource {
    private int value;
    FixedValue(int value) { this.value = value; }
    @Override int nextValue() {
        // ここを実装する
        return 0;
    }
}
public class Main {
    public static void main(String[] args) {
        NumberSource source = new FixedValue(4);
        System.out.println(source.plusOne());
    }
}

