interface Rule {
    boolean allows(int value);
}
class EvenRule implements Rule {
    public boolean allows(int value) { return value % 2 == 0; }
}
class NonNegativeRule implements Rule {
    public boolean allows(int value) { return value >= 0; }
}
class AlwaysRule implements Rule {
    public boolean allows(int value) { return true; }
}
public class Main {
    static int countAllowed(int[] values, Rule rule) {
        int count = 0;
        for (int value : values) {
            if (rule.allows(value)) {
                count = count + 1;
            }
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countAllowed(new int[]{1, 2, 3, 4}, new EvenRule()));
    }
}

